-- GENERATED by scripts/knowledge-seed.mts from Terms.tsx, Privacy.tsx and lib/guides.ts. Do not edit by hand.
-- Needs 0282. Paste whenever it changes; safe to paste again. 87 rows, texts 1d856f9726b0db8f.
begin;
create temporary table _k (id text, source text, audience text, title text, body text, extra text, link text) on commit drop;
insert into _k values
  ('terms:membership', 'terms', 'member', 'Terms 1. Your membership', 'Membership gives you access to the gym during posted opening hours. Membership is paid at the front desk in cash or — where your gym has turned it on — by GCash, Maya or bank transfer into the gym’s own account, which the desk confirms by hand before your plan changes. Where your gym has connected PayMongo, a licensed payment company, you can also pay in the app — by QRPh (scan with GCash, Maya or your bank app), or card and e-wallets where offered. That money goes to the gym’s own PayMongo account, and your plan changes the moment PayMongo confirms it. The app never sees or keeps card details. What the app shows you is the record of what was paid. Switching to a different plan while your current one still runs follows your gym’s own rule, which the app shows you before you pay: either the new plan starts when your current one ends, so no paid day is lost; or it starts at once and the days left on your current plan end, without a refund; or the switch is done at the front desk.', null, '/terms#membership'),
  ('terms:freezing', 'terms', 'member', 'Terms 2. Freezing your membership', 'You may freeze twice in a calendar month. A reason is required.
While frozen you cannot check in or book — a freeze pauses the membership, not attendance alone.
Frozen days are added back to your expiry date, so you are not charged for days you were denied access.
(This part is your gym''s own rule: read it from the gym''s settings.)', null, '/terms#freezing'),
  ('terms:refunds', 'terms', 'member', 'Terms 3. Cancelling, and what you get back', 'Days are counted from the start date of your membership, in Manila time — not from the day you paid.
(This part is your gym''s own rule: read it from the gym''s settings.)
Refunds are paid by the desk — in cash, or back to the GCash, Maya or bank account you paid from.', null, '/terms#refunds'),
  ('terms:floor', 'terms', 'member', 'Terms 4. Why those percentages are a floor', 'Republic Act 7394, the Consumer Act of the Philippines, expects the unused portion of something you prepaid to come back to you. The percentages above are the minimum the gym pays; where a pro-rata calculation comes out higher, you are paid the higher figure. Lowering a tier cannot reduce a payout below what the law expects.', null, '/terms#floor'),
  ('terms:classes', 'terms', 'member', 'Terms 5. Classes and personal training', '(This part is your gym''s own rule: read it from the gym''s settings.)
You cannot be booked into two things at once. A class that overlaps a session you already have is refused, and the app says which booking it clashes with.
Coaches accept or decline their own requests, oldest request first. An admin can reverse a decision.
If a request sits unanswered, the system chases it: your coach after a day, you after two, and an admin after three, so a request cannot quietly expire.', null, '/terms#classes'),
  ('terms:using', 'terms', 'member', 'Terms 6. Using the gym', 'Proper gym attire and footwear are required.
Return equipment to where you found it.
Respect other members and keep the space clean.
No photography or video of other people without their permission.
Your gym may add house rules of its own. They are shown here, dated and numbered, and you are asked to agree to each new version. They can never be changed after they are published — a change is a new version.', null, '/terms#using'),
  ('terms:health', 'terms', 'member', 'Terms 7. Health and safety', 'You use the facilities at your own risk. Talk to a doctor before starting a new programme, and report injuries or broken equipment immediately. The plans and suggestions in this app are generated from fixed rules, not by a medical professional, and they are not medical advice. If you tell the app about an injury it will point you to a professional rather than quietly change your exercises.', null, '/terms#health'),
  ('terms:conduct', 'terms', 'member', 'Terms 8. Conduct', 'Harassment and abusive behaviour are not tolerated, and can end a membership immediately. Ending it does not cancel the refund rules in section 3 — a suspension is recorded with a reason, and the amount owed is worked out the same way it would be for anyone else. If your gym runs a gym chat, the same conduct applies there: everyone in the chat reads what you post. You can remove your own messages; the owner and the front desk can remove any message and can stop a person from posting, and in both cases you are told the reason. You can report a message to the gym, and you can mute the chat''s alerts.', null, '/terms#conduct'),
  ('terms:account', 'terms', 'member', 'Terms 9. Your account', 'When the gym closes your account it is archived, not deleted: your attendance and payment history are the gym''s own records and it has to keep them. You can delete your own account yourself, in Settings → Your data: it is locked at once and erased after 7 days, unless you sign back in and keep it. Erased means your name, contact details, photo, workouts, measurements, photos, chats, assistant conversations and health answers are gone; your payments and visits stay in the gym''s records under "Deleted member". Your future bookings are cancelled when you ask. If your account is suspended, the reason is recorded, and you are told what it is rather than being met with a locked door and no explanation. Core Fitness, which runs the app, can also suspend an account in every gym at once — for fraud, abuse or a legal order. You are shown the reason when you sign in and by email; your gym is told only that Core Fitness suspended it, and only Core Fitness can lift it.', null, '/terms#account'),
  ('terms:streaks', 'terms', 'member', 'Terms 10. Your streak', 'Where your gym runs streaks, a week counts when you check in or log a workout on your own target of days, Monday to Sunday. Rest days never break it.
A week your membership is frozen pauses the streak. After your membership ends, it waits for the number of weeks your gym sets, shown on your streak; renew in that time and it carries on.
Missed a week? You can restore it yourself on the Monday after, free: once a month, rising to five a month as your streak grows (12, 26, 52 and 104 weeks). Not restored that day, it resets to zero. The front desk can also restore a missed week within 14 days, for a reason it records.
A restored week keeps your streak but adds no week to it. Streak points and badges come only from weeks you reached.', null, '/terms#streaks'),
  ('terms:changes', 'terms', 'member', 'Terms 11. Changes to these terms', 'These terms can change. Significant changes are announced in the app rather than quietly edited in, and the date above is updated when they are.', null, '/terms#changes'),
  ('privacy:holds', 'privacy', 'member', 'Privacy 1. What the gym holds about you', 'Your name, email, phone, address and date of birth, and an emergency contact.
Your login: the email and, if you choose one, a username you sign in with. The front desk may make your login for you — with an email or, if you have none, a username — and hand you a one-time password on a printed slip; you choose your own password the first time you sign in, and only then does the slip stop working. The password you choose is never shown to the gym: only a scrambled form of it is kept.
Your profile photo, if you add one — at sign-up or later. The desk and your coach see it, so they know you at the door. You can change or remove it in Profile.
Your check-in code, and every check-in made with it.
Payments — amount, method and date, whether recorded at the desk or paid in the app. No card or bank details: the gym never receives them.
Anything you choose to log: workouts, measurements, and how you rate a coach.
If your gym asks you to sign its waiver: which version you signed and when, and your answers to the seven health questions that come with it. Health answers are sensitive personal information under RA 10173, and are treated as such below.
If your gym runs a gym chat: the messages and photos you post there, your reactions, and any message you report. If it posts reels: which ones you liked.
If your streak is restored: which week, whether you or the front desk restored it, and the reason and note the desk gives. Your coaches see that a week was restored, never why: a reason such as sick or injury is health information, so it stays with the owner and the front desk.
If you turn on notifications, the token your phone needs to receive them. You can turn it off again in Settings.', null, '/privacy#holds'),
  ('privacy:who', 'privacy', 'member', 'Privacy 2. Who can see it', 'You.
The gym owner and the front desk, who need it to run the gym.
Your trainer sees only what you allow. Measurements, and workouts with your saved routines, are each a switch in Settings, and the database itself refuses a trainer the rest — it is not a hidden screen, it is a rule they cannot get around. Progress photos are private to you: only the coaches you train with can see them, and only if you switch on sharing on the Progress photos screen — the gym owner and the front desk never can, and a photo you hand in to a coach as classwork is seen by that coach alone. Your training plan — the days you mean to come in — is visible to the coaches you train with, so they can plan around it, and so is your emergency contact, so a coach can call someone if you are hurt in a session.
The coaches you train with now — a coaching term, a 1-on-1 or a class of theirs in the last 60 days — are told when you make a streak milestone or finish a challenge, and when you set a record if you share workouts with trainers, so they can congratulate you. They see what you reached, never more than your switches already allow.
Your answers to the health questions are seen by the gym owner and the front desk only — not by trainers, whatever your other switches say. A "yes" tells the desk to talk to you before you train hard. It does not stop you training, and nothing in the app changes your workouts because of it.
If you switch gyms (Gyms → Switch gym), and only once you agree on that screen, your workouts and sets, records, routines, weekly plan, body readings, progress photos, earned level and training badges move to the new gym when it accepts you — each gym keeps its own records, so the new gym then holds them. Your payments, visits, points and visit badges stay with the old gym, which is told only that you switched to another gym, never which.
The gym chat, if your gym runs one, is a group: everyone in it — the gym''s active members, its coaches, the front desk and the owner — sees your name, your photo, what you post, your reactions and that you have seen the newest message. Photos posted there open only for people in the chat. A message you report is seen with your name by the owner and the front desk only. When you remove a message, or the gym removes one, its words and photo are erased and only "Message removed" stays in its place. A like on a reel is counted for everyone; who liked it is not shown.
Nobody else. The gym does not sell, rent or trade any of it.', null, '/privacy#who'),
  ('privacy:ratings', 'privacy', 'member', 'Privacy 3. Ratings you give a coach are anonymous to them', 'A coach sees their scores and what was written, with no name attached — the database gives them a view that does not contain who wrote it. The gym can see the name, because a complaint nobody can follow up is not something a gym can act on, and one member quietly rating every coach one star is something it should be able to notice.', null, '/privacy#ratings'),
  ('privacy:where', 'privacy', 'member', 'Privacy 4. Where it is kept', 'In a hosted PostgreSQL database (Supabase, Singapore region) reached over HTTPS, with the app itself served from Vercel. Access is enforced per row in the database, so a screen that forgets to filter still cannot show you somebody else''s records. Your password is never stored by the gym — it is held, hashed, by the authentication service. If you sign up or sign in with Google, Google tells us your name, email address and profile picture, and nothing else; there is then no password with us at all, and the rest of your details are the ones you type in. So the app still works with no signal, your phone also keeps a copy of what your screens last showed, and anything you saved or sent offline until it reaches the database. That copy is filed under your account, is never shown to anyone else who signs in on the same phone, and the saved screens are erased when you log out; anything you saved offline and had not yet sent stays on the phone, still yours, and goes the next time you sign in there.', null, '/privacy#where'),
  ('privacy:not', 'privacy', 'member', 'Privacy 5. What this app does not do', 'No advertising, and no advertising identifiers.
No analytics or usage tracking, and no third-party tracking scripts.
Paying in the app — only where your gym has connected PayMongo, a licensed payment company. PayMongo then receives what the payment needs: your name, email, the amount and how you pay (card details go to PayMongo only, never to the gym or this app). Otherwise you pay the gym in cash at the desk or, where it offers it, from your own GCash, Maya or bank app; if you pay that way, the reference number and the screenshot you send are kept with your payment record.
The in-app assistant answers questions about your membership, bookings and the gym from fixed rules, in the app. At gyms and on plans that include the AI assistant, questions the rules cannot answer are sent to Anthropic, the company that runs the model, to be answered. The assistant sees your first name, how much you train, routines, your weekly plan and how often you have trained lately, only if you say yes when it first asks (Settings changes it); it never sees your health questionnaire (PAR-Q) or waiver answers, payments, contact details, chats with coaches or photos. What you tell the assistant when it sets you up — your goal, experience, how often and how long you train, your equipment, what you enjoy or avoid, and whether something hurts (a yes or no, never the details) — is kept for the assistant and sent to Anthropic with each question you ask it, even if you do not let it read your training. Your conversations are kept in the gym''s database, visible only to you, and you can delete them. The assistant can suggest changes to your routines, your weekly plan and your goals; nothing changes until you tap Apply, and you can undo a change afterwards. The gym''s coaches and front desk can see which of your routines and plan days were made by the assistant (a small mark on them), never your conversation. Meal guides were removed on 5 October 2026; one you applied before then is kept only in your own data export, and nobody else sees it.', null, '/privacy#not'),
  ('privacy:rights', 'privacy', 'member', 'Privacy 6. Your rights under RA 10173', 'See what is held about you: Settings → Your data downloads a copy of all of it as one file, and the front desk can give you the same file. Have anything wrong corrected — most details you can change yourself in Edit profile; ask at the desk for the rest and it is fixed the same day.
Object to receiving announcements: notification preferences are yours, in Settings.
Complain to the National Privacy Commission if the gym gets this wrong.
Delete your account: Settings → Your data → Delete my account. It is locked at once and erased after 7 days — sign back in within them to keep it. Erasing removes your name, email, phone, photo, address, birthday, emergency contact, workouts, routines, programs, plans, measurements, targets, records, progress photos, chats, assistant conversations, health (PAR-Q) answers, badges and notifications, and closes your sign-in. One limit, stated plainly: your payments, receipts, memberships and visits are the gym''s own accounting records, so they stay — under the name "Deleted member", with nothing left that says who you were. When the gym itself closes your account, it is archived instead: access ends, you leave the roster, and the records behind it stay.', null, '/privacy#rights'),
  ('privacy:kept', 'privacy', 'member', 'Privacy 7. How long it is kept', 'For as long as you are a member, and afterwards for as long as the gym needs its own financial and attendance records. What you logged for yourself — workouts and measurements — is kept with your account so your history is still there if you come back — until you delete your account, when it is erased 7 days later (section 6). That includes what you posted in the gym chat and any reels you posted: they are erased with the account.', null, '/privacy#kept'),
  ('privacy:minors', 'privacy', 'member', 'Privacy 8. Under 18', 'A member under 18 needs a parent or guardian to sign them up and to agree to this policy at the desk.', null, '/privacy#minors'),
  ('privacy:changes', 'privacy', 'member', 'Privacy 9. Changes to this policy', 'If this changes in a way that matters, it is announced in the app and the date above changes with it.', null, '/privacy#changes'),
  ('guide:online-pay', 'guide', 'staff', 'Guide: Online payments (PayMongo)', 'Members pay you in the app by GCash, Maya or card: straight to your own PayMongo account.', 'Online na bayad (PayMongo). Magbabayad ang members sa app gamit ang GCash, Maya o card: diretso sa sarili mong PayMongo account.', '/gym-app?tab=pay'),
  ('guide:online-pay:1', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 1: Make a PayMongo account', 'At paymongo.com, with your gym’s email. Opening it is free; PayMongo takes a fee from each payment.', 'Gumawa ng PayMongo account. Sa paymongo.com, gamit ang email ng gym mo. Libre ang pagbukas; may kaltas ang PayMongo sa bawat bayad.', '/gym-app?tab=pay'),
  ('guide:online-pay:2', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 2: Get your business checked', 'PayMongo asks for your DTI or SEC registration, a valid ID and the bank account it pays you out to. Until it activates you, only test mode works: that is fine for trying it.', 'Ipa-verify ang negosyo mo. Hihingin ng PayMongo ang DTI o SEC registration, valid ID at bank account na paghuhulugan ng pera. Habang hindi pa activated, test mode lang ang gagana: ayos lang iyon para masubukan.', '/gym-app?tab=pay'),
  ('guide:online-pay:3', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 3: Copy your secret key', 'Developers → API keys. It starts with sk_test_ (test) or sk_live_ (real money). Never share it.', 'Kopyahin ang secret key. Developers → API keys. Nagsisimula ito sa sk_test_ (test) o sk_live_ (totoong pera). Huwag itong ibigay kahit kanino.', '/gym-app?tab=pay'),
  ('guide:online-pay:4', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 4: Paste it in Your app → Payments', 'Paste the key and press Connect PayMongo. Core Fitness checks it with PayMongo and stores it encrypted: it is never shown again.', 'I-paste sa Your app → Payments. I-paste ang key at pindutin ang Connect PayMongo. Susuriin ito ng Core Fitness sa PayMongo at itatago nang naka-encrypt: hindi na ito ipapakita ulit.', '/gym-app?tab=pay'),
  ('guide:online-pay:5', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 5: Try it with no real money', 'In the member app, renew a plan and choose Pay in the app. Use one of PayMongo’s test cards. It appears in Payments with a receipt number.', 'Subukan nang walang totoong pera. Sa member app, mag-renew ng plan at piliin ang Pay in the app. Gamitin ang test card ng PayMongo. Lalabas ito sa Payments na may receipt number.', '/gym-app?tab=pay'),
  ('guide:online-pay:6', 'guide', 'staff', 'Guide: Online payments (PayMongo), step 6: Go live', 'When PayMongo activates you, connect your sk_live_ key the same way. Money lands in your PayMongo balance and is paid out to your bank: Core Fitness never holds it.', 'Gawing live. Kapag activated ka na ng PayMongo, i-connect ang sk_live_ key sa parehong paraan. Papasok ang pera sa PayMongo balance mo at ihuhulog sa bangko mo: hindi ito hinahawakan ng Core Fitness.', '/gym-app?tab=pay'),
  ('guide:kiosk', 'guide', 'staff', 'Guide: Self check-in kiosk', 'A computer or tablet by the door checks members in by their QR: no one needed at the desk.', 'Kiosk para sa sariling check-in. Isang computer o tablet sa pinto ang magche-check in sa members gamit ang QR nila: kahit walang tao sa desk.', '/attendance'),
  ('guide:kiosk:1', 'guide', 'staff', 'Guide: Self check-in kiosk, step 1: What you need', 'A laptop or PC with a webcam, or a tablet, placed by the door. It stays signed in as the owner or the front desk.', 'Ang kailangan mo. Isang laptop o PC na may webcam, o isang tablet, sa may pinto. Naka-sign in ito bilang owner o front desk.', '/attendance'),
  ('guide:kiosk:2', 'guide', 'staff', 'Guide: Self check-in kiosk, step 2: Open it from Attendance', 'Attendance → Open kiosk. When the browser asks to use the camera, press Allow.', 'Buksan sa Attendance. Attendance → Open kiosk. Kapag nagtanong ang browser kung puwedeng gamitin ang camera, pindutin ang Allow.', '/attendance'),
  ('guide:kiosk:3', 'guide', 'staff', 'Guide: Self check-in kiosk, step 3: Members show their QR', 'They tap Check in in their app and hold the QR up to the camera: or type their six-character code.', 'Ipapakita ng member ang QR nila. Pipindutin nila ang Check in sa app at itatapat ang QR sa camera: o ita-type ang anim na letrang code nila.', '/attendance'),
  ('guide:kiosk:4', 'guide', 'staff', 'Guide: Self check-in kiosk, step 4: Checked in, with the desk’s rules', 'The screen shows only their first name and “checked in”. A frozen or expired membership is refused, as at the desk.', 'Naka-check in, sa parehong patakaran ng desk. Pangalan lang at “checked in” ang lalabas. Hindi tatanggapin ang frozen o expired na membership, gaya sa desk.', '/attendance'),
  ('guide:kiosk:5', 'guide', 'staff', 'Guide: Self check-in kiosk, step 5: Leaving the kiosk', 'Press and hold Exit. A quick tap from someone in line will not unlock the desk.', 'Paglabas sa kiosk. Pindutin nang matagal ang Exit. Hindi ito mabubuksan ng mabilis na pindot ng nakapila.', '/attendance'),
  ('guide:lobby-tv', 'guide', 'staff', 'Guide: Lobby TV', 'Today’s classes, check-ins and announcements on a TV in your gym, updating by itself.', 'Lobby TV. Mga klase ngayon, check-ins at anunsyo sa TV ng gym mo, kusang nag-a-update.', '/gym-app?tab=tv'),
  ('guide:lobby-tv:1', 'guide', 'staff', 'Guide: Lobby TV, step 1: Switch it on', 'Your app → What you run → A lobby TV? → Yes. It needs a Core Fitness plan that includes the TV (Your plan shows which).', 'I-on ito. Your app → What you run → A lobby TV? → Yes. Kailangang kasama ang TV sa Core Fitness plan mo (makikita sa Your plan).', '/gym-app?tab=tv'),
  ('guide:lobby-tv:2', 'guide', 'staff', 'Guide: Lobby TV, step 2: Design it', 'Your app → Lobby TV: a headline, which panels to show and how many seconds each stays up.', 'Ayusin ang itsura. Your app → Lobby TV: isang headline, aling panels ang ipapakita at ilang segundo bawat isa.', '/gym-app?tab=tv'),
  ('guide:lobby-tv:3', 'guide', 'staff', 'Guide: Lobby TV, step 3: Connect a computer to the TV', 'Any gym computer, plugged into the TV with an HDMI cable, signed in as the owner or the desk.', 'Ikonekta ang computer sa TV. Kahit anong computer ng gym, nakakabit sa TV gamit ang HDMI cable, naka-sign in bilang owner o desk.', '/gym-app?tab=tv'),
  ('guide:lobby-tv:4', 'guide', 'staff', 'Guide: Lobby TV, step 4: Open the TV, full screen', 'Press Open the TV (or go to /tv) and press F11 for full screen.', 'Buksan ang TV, full screen. Pindutin ang Open the TV (o pumunta sa /tv) at pindutin ang F11 para full screen.', '/gym-app?tab=tv'),
  ('guide:lobby-tv:5', 'guide', 'staff', 'Guide: Lobby TV, step 5: Leave it on: it is live', 'It updates by itself every 10 seconds: check-ins, today’s classes, announcements.', 'Iwanang bukas: live ito. Kusang nag-a-update kada 10 segundo: check-ins, mga klase ngayon, mga anunsyo.', '/gym-app?tab=tv'),
  ('guide:door-checkin', 'guide', 'staff', 'Guide: Coach check-in and activities', 'Coaches check in with their own QR; members can tag what they are doing today.', 'Check-in ng coach at mga activity. Magche-check in ang coaches gamit ang sarili nilang QR; puwedeng i-tag ng members kung ano ang gagawin nila ngayon.', '/settings?tab=checkin'),
  ('guide:door-checkin:1', 'guide', 'staff', 'Guide: Coach check-in and activities, step 1: Settings → Checking in', 'Everything about the door is on this tab.', 'Settings → Checking in. Nandito lahat tungkol sa pag-check in.', '/settings?tab=checkin'),
  ('guide:door-checkin:2', 'guide', 'staff', 'Guide: Coach check-in and activities, step 2: Coaches check in too', 'Each coach gets a QR in their app. The desk or the kiosk scans it; you see who came in on Attendance → Today. A coach is never counted as a member visit.', 'Mag-check in din ang coaches. Bawat coach ay may QR sa app nila. Isa-scan ito ng desk o kiosk; makikita mo kung sino ang dumating sa Attendance → Today. Hindi ito binibilang na member visit.', '/settings?tab=checkin'),
  ('guide:door-checkin:3', 'guide', 'staff', 'Guide: Coach check-in and activities, step 3: Members pick their activity', 'Members tap what they are doing today on their QR screen and can make it their usual. The desk’s own tag still wins.', 'Pipili ang member ng activity. Pipindutin ng member ang gagawin nila ngayon sa QR screen at puwedeng gawing “usual”. Ang tag ng desk pa rin ang masusunod.', '/settings?tab=checkin'),
  ('guide:invite', 'guide', 'staff', 'Guide: Invite staff, coaches and members', 'Each invitation is a login: they get a one-time password and set their own at first sign-in.', 'Mag-imbita ng staff, coach at members. Bawat imbitasyon ay isang login: may one-time password sila at gagawa ng sariling password sa unang sign-in.', '/invitations'),
  ('guide:invite:1', 'guide', 'staff', 'Guide: Invite staff, coaches and members, step 1: People → Invitations', 'Choose who is joining: Member, Coach or Front desk.', 'People → Invitations. Piliin kung sino ang sasali: Member, Coach o Front desk.', '/invitations'),
  ('guide:invite:2', 'guide', 'staff', 'Guide: Invite staff, coaches and members, step 2: Add them', 'An email each (name and mobile optional), or many at once from a CSV. No email? Use a username instead.', 'Idagdag sila. Isang email bawat tao (opsyonal ang pangalan at mobile), o marami nang sabay mula sa CSV. Walang email? Gumamit ng username.', '/invitations'),
  ('guide:invite:3', 'guide', 'staff', 'Guide: Invite staff, coaches and members, step 3: Hand over the login slip', 'A slip shows their username or email and a one-time password. Print it or show it. Emailed invites get it by email.', 'Ibigay ang login slip. Nakasulat sa slip ang username o email at one-time password nila. I-print o ipakita. Ang may email ay matatanggap ito sa email.', '/invitations'),
  ('guide:invite:4', 'guide', 'staff', 'Guide: Invite staff, coaches and members, step 4: They sign in once, then choose a password', 'Front desk signs in to this dashboard; coaches and members to the phone app (coaches on its Trainer tab). At first sign-in they set their own password.', 'Mag-sign in sila, tapos pipili ng password. Sa dashboard na ito magsa-sign in ang front desk; sa phone app ang coaches at members (Trainer tab para sa coaches). Sa unang sign-in, gagawa sila ng sariling password.', '/invitations'),
  ('guide:plans', 'guide', 'staff', 'Guide: Plans and prices', 'What you sell, what each plan unlocks, and how members renew.', 'Mga plan at presyo. Ang mga binebenta mo, ano ang kasama sa bawat plan, at paano mag-renew ang members.', '/membership-plans'),
  ('guide:plans:1', 'guide', 'staff', 'Guide: Plans and prices, step 1: Billing → Plans', 'Your plans on sale, what each unlocks, and members on a paid plan.', 'Billing → Plans. Ang mga plan na binebenta mo, ano ang kasama, at mga member na may bayad na plan.', '/membership-plans'),
  ('guide:plans:2', 'guide', 'staff', 'Guide: Plans and prices, step 2: Add a plan', 'New plan → the name members see, the price (₱), how long it lasts and what it unlocks (class bookings, coaching).', 'Magdagdag ng plan. New plan → ang pangalang makikita ng members, presyo (₱), gaano katagal, at ano ang kasama (class bookings, coaching).', '/membership-plans'),
  ('guide:plans:3', 'guide', 'staff', 'Guide: Plans and prices, step 3: Members see it in their app', 'They choose it when they renew: at your desk, or in the app if online payments are on.', 'Makikita ito ng members sa app. Pipiliin nila ito kapag nag-renew: sa desk mo, o sa app kung naka-on ang online payments.', '/membership-plans'),
  ('guide:plans:4', 'guide', 'staff', 'Guide: Plans and prices, step 4: Stop selling one', 'Retire it instead of deleting: members already on it keep it, and its history stays.', 'Itigil ang pagbenta ng isa. I-retire imbes na burahin: tuloy pa rin sa mga member na nasa plan na iyon, at mananatili ang history.', '/membership-plans'),
  ('guide:reels', 'guide', 'staff', 'Guide: Reels', 'Short videos for your members: paste a link or upload your own.', 'Reels. Maiikling video para sa members: mag-paste ng link o mag-upload.', '/reels'),
  ('guide:reels:1', 'guide', 'staff', 'Guide: Reels, step 1: Switch it on', 'Your app → What you run → Reels? → Yes. Until then the page stays hidden.', 'I-on ito. Your app → What you run → Reels? → Yes. Nakatago ang page hangga’t hindi naka-on.', '/reels'),
  ('guide:reels:2', 'guide', 'staff', 'Guide: Reels, step 2: Training → Reels → post', 'Paste a YouTube, TikTok, Facebook or Instagram link, or upload a short video (up to 15 MB). You, the desk and coaches can post.', 'Training → Reels → mag-post. Mag-paste ng link mula YouTube, TikTok, Facebook o Instagram, o mag-upload ng maikling video (hanggang 15 MB). Puwedeng mag-post ikaw, ang desk at coaches.', '/reels'),
  ('guide:reels:3', 'guide', 'staff', 'Guide: Reels, step 3: Members watch on Today', 'A strip on their Today screen and a full Reels page, with likes.', 'Panonoorin ng members sa Today. May hanay sa Today screen nila at buong Reels page, may likes.', '/reels'),
  ('guide:reels:4', 'guide', 'staff', 'Guide: Reels, step 4: Edit, hide or remove', 'You can edit, hide or remove any reel; the desk and coaches manage their own. Turn Coaches post reels off to keep coaches from posting new ones.', 'I-edit, itago o burahin. Puwede mong i-edit, itago o burahin ang kahit anong reel; sariling post lang ang sa desk at coaches. I-off ang Coaches post reels para hindi na makapag-post ng bago ang coaches.', '/reels'),
  ('guide:gym-chat', 'guide', 'staff', 'Guide: Gym chat', 'One group chat for your members, coaches, front desk and you.', 'Gym chat. Isang group chat para sa members, coaches, front desk at ikaw.', '/gym-chat'),
  ('guide:gym-chat:1', 'guide', 'staff', 'Guide: Gym chat, step 1: Switch it on', 'Your app → What you run → A group chat for your gym? → Yes. Members with a membership that is active today are in it.', 'I-on ito. Your app → What you run → A group chat for your gym? → Yes. Kasali ang members na may aktibong membership ngayon.', '/gym-chat'),
  ('guide:gym-chat:2', 'guide', 'staff', 'Guide: Gym chat, step 2: Everyone chats in one place', 'Members open it from the chat button in their app; you and the desk from Messages, then Gym chat. Every message can be a push.', 'Iisang lugar ang usapan. Bubuksan ito ng members sa chat button ng app; ikaw at ang desk sa Messages, tapos Gym chat. Puwedeng may push ang bawat mensahe.', '/gym-chat'),
  ('guide:gym-chat:3', 'guide', 'staff', 'Guide: Gym chat, step 3: Keep it tidy', 'Pin up to three messages, remove one with a reason, silence someone, or set announce-only so only staff and coaches post.', 'Panatilihing maayos. Mag-pin ng hanggang tatlong mensahe, mag-alis nang may dahilan, patahimikin ang isang tao, o gawing announce-only para staff at coaches lang ang makapag-post.', '/gym-chat'),
  ('guide:day-pass', 'guide', 'staff', 'Guide: Day passes for walk-ins', 'Sell a one-day visit (or packs of 5 or 10) to guests without a membership.', 'Day pass para sa walk-ins. Magbenta ng isang araw na pasok (o pack ng 5 o 10) sa guests na walang membership.', '/settings?tab=walk-ins'),
  ('guide:day-pass:1', 'guide', 'staff', 'Guide: Day passes for walk-ins, step 1: Settings → Walk-ins', 'Turn on Sell day passes to walk-ins.', 'Settings → Walk-ins. I-on ang Sell day passes to walk-ins.', '/settings?tab=walk-ins'),
  ('guide:day-pass:2', 'guide', 'staff', 'Guide: Day passes for walk-ins, step 2: Set the prices', 'A day pass, and packs of 5 and 10 if you sell them. Choose whether guests can book a class that day.', 'Ilagay ang presyo. Presyo ng day pass, at ng pack ng 5 at 10 kung meron. Piliin kung puwedeng mag-book ng klase ang guest sa araw na iyon.', '/settings?tab=walk-ins'),
  ('guide:day-pass:3', 'guide', 'staff', 'Guide: Day passes for walk-ins, step 3: Sell one at the desk', 'Attendance → Walk-ins. A guest with today’s pass is checked in like a member.', 'Magbenta sa desk. Attendance → Walk-ins. Ang guest na may pass ngayong araw ay mache-check in na parang member.', '/settings?tab=walk-ins'),
  ('guide:shop', 'guide', 'staff', 'Guide: Shop', 'Sell drinks, supplements and gear at the desk, with stock counted for you.', 'Shop. Magbenta ng inumin, supplements at gamit sa desk, at bilang ang stock para sa iyo.', '/shop'),
  ('guide:shop:1', 'guide', 'staff', 'Guide: Shop, step 1: Billing → Shop', 'Add each product with a photo, a price and, if you want, its stock.', 'Billing → Shop. Idagdag ang bawat produkto na may litrato, presyo at, kung gusto mo, stock.', '/shop'),
  ('guide:shop:2', 'guide', 'staff', 'Guide: Shop, step 2: Ring up a sale', 'Tap the products on the ticket and record the sale; the stock goes down by itself.', 'Mag-ring up ng benta. Pindutin ang mga produkto sa ticket at i-record ang benta; kusang bababa ang stock.', '/shop'),
  ('guide:shop:3', 'guide', 'staff', 'Guide: Shop, step 3: Know when to restock', 'Products running low are listed so you can restock in time.', 'Alamin kung kailan magre-restock. Nakalista ang mga paubos na produkto para makapag-restock ka agad.', '/shop'),
  ('guide:rewards', 'guide', 'staff', 'Guide: Points and rewards', 'Members earn points for coming in and training, and spend them on rewards you set.', 'Points at rewards. Nag-iipon ng points ang members sa pagpunta at pag-training, at ginagastos sa rewards na itinakda mo.', '/rewards'),
  ('guide:rewards:1', 'guide', 'staff', 'Guide: Points and rewards, step 1: Switch it on', 'Your app → What you run → Points and rewards? → Yes, and name your points if you like.', 'I-on ito. Your app → What you run → Points and rewards? → Yes, at pangalanan ang points kung gusto mo.', '/rewards'),
  ('guide:rewards:2', 'guide', 'staff', 'Guide: Points and rewards, step 2: Engagement → Rewards', 'Add rewards and how many points each costs.', 'Engagement → Rewards. Magdagdag ng rewards at ilang points ang halaga ng bawat isa.', '/rewards'),
  ('guide:rewards:3', 'guide', 'staff', 'Guide: Points and rewards, step 3: Hand it over', 'A member claims one in the app; it shows under Requests. Approve it and hand it over at the desk.', 'Ibigay ang reward. Kukunin ito ng member sa app; lalabas sa Requests. I-approve at iabot sa desk.', '/rewards'),
  ('guide:waiver', 'guide', 'staff', 'Guide: Waiver and health questions', 'Members sign your waiver in the app before booking.', 'Waiver at health questions. Pipirmahan ng members ang waiver mo sa app bago mag-book.', '/settings?tab=waiver'),
  ('guide:waiver:1', 'guide', 'staff', 'Guide: Waiver and health questions, step 1: Settings → Waiver', 'Write your waiver and publish it.', 'Settings → Waiver. Isulat ang waiver mo at i-publish.', '/settings?tab=waiver'),
  ('guide:waiver:2', 'guide', 'staff', 'Guide: Waiver and health questions, step 2: Published words never change', 'Editing makes the next version; every signature keeps the words that person was shown.', 'Hindi na nababago ang na-publish. Ang pag-edit ay gagawa ng bagong bersyon; nakatabi sa bawat pirma ang mismong salitang nabasa ng tao.', '/settings?tab=waiver'),
  ('guide:waiver:3', 'guide', 'staff', 'Guide: Waiver and health questions, step 3: Members sign before booking', 'With the health questions (PAR-Q). A “yes” suggests seeing a doctor; it never blocks them. Only the desk sees the answers, never coaches.', 'Pipirma ang members bago mag-book. Kasama ang health questions (PAR-Q). Ang “yes” ay payo na kumonsulta sa doktor; hindi sila hinaharang. Desk lang ang nakakakita ng sagot, hindi coaches.', '/settings?tab=waiver'),
  ('guide:install-app', 'guide', 'member', 'Guide: Install the app on your phone', 'Android or iPhone: the same app, no app store needed.', 'I-install ang app sa phone. Android o iPhone: iisang app, hindi kailangan ng app store.', null),
  ('guide:install-app:1', 'guide', 'member', 'Guide: Install the app on your phone, step 1: Android: open the download page in Chrome', 'Go to corefitness-gym.vercel.app/get-app and press the download button.', 'Android: buksan ang download page sa Chrome. Pumunta sa corefitness-gym.vercel.app/get-app at pindutin ang download button.', null),
  ('guide:install-app:2', 'guide', 'member', 'Guide: Install the app on your phone, step 2: Allow the install', 'Open the downloaded file. If the phone asks, allow Chrome to install apps, then press Install. Or, in Chrome’s menu, tap Install app.', 'Payagan ang pag-install. Buksan ang na-download na file. Kapag nagtanong ang phone, payagan ang Chrome na mag-install, tapos pindutin ang Install. O sa menu ng Chrome, pindutin ang Install app.', null),
  ('guide:install-app:3', 'guide', 'member', 'Guide: Install the app on your phone, step 3: iPhone: Safari → Share → Add to Home Screen', 'Open the same address in Safari, tap Share, then Add to Home Screen. It opens like any app.', 'iPhone: Safari → Share → Add to Home Screen. Buksan ang parehong address sa Safari, pindutin ang Share, tapos Add to Home Screen. Bubukas ito na parang ibang app.', null),
  ('guide:install-app:4', 'guide', 'member', 'Guide: Install the app on your phone, step 4: Sign in once', 'You stay signed in until you press Log out on that phone.', 'Mag-sign in nang isang beses. Mananatili kang naka-sign in hanggang pindutin mo ang Log out sa phone na iyon.', null),
  ('guide:notifications', 'guide', 'member', 'Guide: Turn on notifications', 'Bookings, payments, coach notes and messages on your phone, even with the app closed.', 'I-on ang notifications. Bookings, bayad, notes ng coach at mensahe sa phone mo, kahit sarado ang app.', null),
  ('guide:notifications:1', 'guide', 'member', 'Guide: Turn on notifications, step 1: Press Turn on', 'On Today, the Turn on notifications card: or Settings → Notifications.', 'Pindutin ang Turn on. Sa Today, ang Turn on notifications card: o Settings → Notifications.', null),
  ('guide:notifications:2', 'guide', 'member', 'Guide: Turn on notifications, step 2: Allow them', 'When the phone asks, press Allow. Everything still lands in the bell either way.', 'Payagan. Kapag nagtanong ang phone, pindutin ang Allow. Lalabas pa rin lahat sa bell kahit ano ang piliin.', null),
  ('guide:notifications:3', 'guide', 'member', 'Guide: Turn on notifications, step 3: Android: let them pop on screen', 'Phone Settings → Apps → Core Fitness → Notifications → turn on Pop on screen, so they show over other apps.', 'Android: hayaang lumabas sa screen. Settings ng phone → Apps → Core Fitness → Notifications → i-on ang Pop on screen, para lumabas kahit nasa ibang app ka.', null);
delete from knowledge_chunks c where not exists (select 1 from _k where _k.id = c.id);
insert into knowledge_chunks (id, source, audience, title, body, extra, link)
select id, source, audience, title, body, extra, link from _k
on conflict (id) do update set source = excluded.source, audience = excluded.audience, title = excluded.title,
  body = excluded.body, extra = excluded.extra, link = excluded.link;
insert into knowledge_meta (id, texts_hash, updated_at) values (true, '1d856f9726b0db8f', now())
on conflict (id) do update set texts_hash = excluded.texts_hash, updated_at = excluded.updated_at;
commit;
